solution.javascript:
function canFinish(numCourses, prerequisites) {
  const adj = Array.from({length: numCourses}, () => []);
  for (const [a,b] of prerequisites) adj[b].push(a);
  const state = Array(numCourses).fill(0);
  function hasCycle(v) {
    if (state[v] === 1) return true;
    if (state[v] === 2) return false;
    state[v] = 1;
    for (const u of adj[v]) if (hasCycle(u)) return true;
    state[v] = 2;
    return false;
  }
  for (let i = 0; i < numCourses; i++) if (hasCycle(i)) return false;
  return true;
}

solution.cpp:
bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
    vector<vector<int>> adj(numCourses);
    for (auto& p : prerequisites) adj[p[1]].push_back(p[0]);
    vector<int> state(numCourses);
    function<bool(int)> hasCycle = [&](int v) {
        if (state[v]==1) return true;
        if (state[v]==2) return false;
        state[v] = 1;
        for (int u : adj[v]) if (hasCycle(u)) return true;
        state[v] = 2;
        return false;
    };
    for (int i=0;i<numCourses;i++) if (hasCycle(i)) return false;
    return true;
}
